  v_res := public.hard_stop_decide('{"id":"acc-A","initial_balance":50000,"rules":{"trailingMaxDrawdown":2000,"enableHardStop":true,"maxDailyLoss":1000,"maxDailyLossType":"$","resetTz":"Not/AZone"}}'::jsonb, '[{"id":"t1","account_id":"acc-A","pnl":-1000,"date":"2026-03-09T16:30:00.000Z"}]'::jsonb, NULL, NULL, NULL, NULL, '2026-03-09T18:00:00Z'::timestamptz);
