         AND (v_res->>'dayKey') IS NOT DISTINCT FROM '2026-03-10'
         AND abs((v_res->>'lossToday')::numeric - (301)::numeric) <= 1e-9
         AND abs((v_res->>'limit')::numeric - (300.00300000000004)::numeric) <= 1e-9
         AND (v_res->>'allowed') = 'false'
         AND (v_res->>'code') IS NOT DISTINCT FROM 'HARD_STOP', false) THEN
    v_fail := v_fail || ('P5 percent decimal limit (3% of 10000.10) above the limit: locked' || ': ' || v_res::text);
  END IF;
  -- P5 percent decimal limit (3% of 10000.10) below the limit: warn
  v_res := public.hard_stop_decide('{"id":"acc-A","initial_balance":10000.1,"rules":{"enableHardStop":true,"maxDailyLoss":3,"maxDailyLossType":"%"}}'::jsonb, '[{"id":"t1","account_id":"acc-A","pnl":-299,"date":"2026-03-10T10:00:00.000Z"}]'::jsonb, 'UTC', 'INSERT', NULL, '{"account_id":"acc-A","pnl":-1}'::jsonb, '2026-03-10T15:00:00Z'::timestamptz);
  v_run := v_run + 1;
  IF NOT coalesce((v_res->>'status') IS NOT DISTINCT FROM 'warn'
         AND (v_res->>'dayKey') IS NOT DISTINCT FROM '2026-03-10'
         AND abs((v_res->>'lossToday')::numeric - (299)::numeric) <= 1e-9
         AND abs((v_res->>'limit')::numeric - (300.00300000000004)::numeric) <= 1e-9
         AND (v_res->>'allowed') = 'true'
         AND (v_res->>'code') IS NOT DISTINCT FROM NULL, false) THEN
    v_fail := v_fail || ('P5 percent decimal limit (3% of 10000.10) below the limit: warn' || ': ' || v_res::text);
  END IF;
  -- P5 dailyLossAlertThreshold 0 falls back to 80: warn at 80%
  v_res := public.hard_stop_decide('{"id":"acc-A","initial_balance":50000,"rules":{"trailingMaxDrawdown":2000,"enableHardStop":true,"maxDailyLoss":1000,"maxDailyLossType":"$","dailyLossAlertThreshold":0}}'::jsonb, '[{"id":"t1","account_id":"acc-A","pnl":-800,"date":"2026-03-10T10:00:00.000Z"}]'::jsonb, 'UTC', NULL, NULL, NULL, '2026-03-10T15:00:00Z'::timestamptz);
  v_run := v_run + 1;
  IF NOT coalesce((v_res->>'status') IS NOT DISTINCT FROM 'warn'
         AND (v_res->>'dayKey') IS NOT DISTINCT FROM '2026-03-10'
         AND abs((v_res->>'lossToday')::numeric - (800)::numeric) <= 1e-9
         AND abs((v_res->>'limit')::numeric - (1000)::numeric) <= 1e-9, false) THEN
    v_fail := v_fail || ('P5 dailyLossAlertThreshold 0 falls back to 80: warn at 80%' || ': ' || v_res::text);
  END IF;
  -- P5 dailyLossAlertThreshold negative falls back to 80: ok at 79%
  v_res := public.hard_stop_decide('{"id":"acc-A","initial_balance":50000,"rules":{"trailingMaxDrawdown":2000,"enableHardStop":true,"maxDailyLoss":1000,"maxDailyLossType":"$","dailyLossAlertThreshold":-5}}'::jsonb, '[{"id":"t1","account_id":"acc-A","pnl":-790,"date":"2026-03-10T10:00:00.000Z"}]'::jsonb, 'UTC', NULL, NULL, NULL, '2026-03-10T15:00:00Z'::timestamptz);
  v_run := v_run + 1;
  IF NOT coalesce((v_res->>'status') IS NOT DISTINCT FROM 'ok'
         AND (v_res->>'dayKey') IS NOT DISTINCT FROM '2026-03-10'
         AND abs((v_res->>'lossToday')::numeric - (790)::numeric) <= 1e-9
         AND abs((v_res->>'limit')::numeric - (1000)::numeric) <= 1e-9, false) THEN
    v_fail := v_fail || ('P5 dailyLossAlertThreshold negative falls back to 80: ok at 79%' || ': ' || v_res::text);
  END IF;
  -- P5 dailyLossAlertThreshold string "50" falls back to 80: ok at 60%
  v_res := public.hard_stop_decide('{"id":"acc-A","initial_balance":50000,"rules":{"trailingMaxDrawdown":2000,"enableHardStop":true,"maxDailyLoss":1000,"maxDailyLossType":"$","dailyLossAlertThreshold":"50"}}'::jsonb, '[{"id":"t1","account_id":"acc-A","pnl":-600,"date":"2026-03-10T10:00:00.000Z"}]'::jsonb, 'UTC', NULL, NULL, NULL, '2026-03-10T15:00:00Z'::timestamptz);
  v_run := v_run + 1;
  IF NOT coalesce((v_res->>'status') IS NOT DISTINCT FROM 'ok'
         AND (v_res->>'dayKey') IS NOT DISTINCT FROM '2026-03-10'
         AND abs((v_res->>'lossToday')::numeric - (600)::numeric) <= 1e-9
         AND abs((v_res->>'limit')::numeric - (1000)::numeric) <= 1e-9, false) THEN
    v_fail := v_fail || ('P5 dailyLossAlertThreshold string "50" falls back to 80: ok at 60%' || ': ' || v_res::text);
  END IF;
  -- P5 dailyLossAlertThreshold null falls back to 80: warn at 80%
  v_res := public.hard_stop_decide('{"id":"acc-A","initial_balance":50000,"rules":{"trailingMaxDrawdown":2000,"enableHardStop":true,"maxDailyLoss":1000,"maxDailyLossType":"$","dailyLossAlertThreshold":null}}'::jsonb, '[{"id":"t1","account_id":"acc-A","pnl":-800,"date":"2026-03-10T10:00:00.000Z"}]'::jsonb, 'UTC', NULL, NULL, NULL, '2026-03-10T15:00:00Z'::timestamptz);
  v_run := v_run + 1;
  IF NOT coalesce((v_res->>'status') IS NOT DISTINCT FROM 'warn'
         AND (v_res->>'dayKey') IS NOT DISTINCT FROM '2026-03-10'
         AND abs((v_res->>'lossToday')::numeric - (800)::numeric) <= 1e-9
         AND abs((v_res->>'limit')::numeric - (1000)::numeric) <= 1e-9, false) THEN
    v_fail := v_fail || ('P5 dailyLossAlertThreshold null falls back to 80: warn at 80%' || ': ' || v_res::text);
  END IF;
  -- P5 maxDailyLoss string "1000" is not configured: off
  v_res := public.hard_stop_decide('{"id":"acc-A","initial_balance":50000,"rules":{"trailingMaxDrawdown":2000,"enableHardStop":true,"maxDailyLoss":"1000","maxDailyLossType":"$"}}'::jsonb, '[{"id":"t1","account_id":"acc-A","pnl":-1000,"date":"2026-03-10T10:00:00.000Z"}]'::jsonb, 'UTC', 'INSERT', NULL, '{"account_id":"acc-A","pnl":-1}'::jsonb, '2026-03-10T15:00:00Z'::timestamptz);
  v_run := v_run + 1;
  IF NOT coalesce((v_res->>'status') IS NOT DISTINCT FROM 'off'
         AND (v_res->>'dayKey') IS NOT DISTINCT FROM '2026-03-10'
         AND abs((v_res->>'lossToday')::numeric - (1000)::numeric) <= 1e-9
         AND (v_res->>'limit') IS NULL
         AND (v_res->>'allowed') = 'true'
         AND (v_res->>'code') IS NOT DISTINCT FROM NULL, false) THEN
    v_fail := v_fail || ('P5 maxDailyLoss string "1000" is not configured: off' || ': ' || v_res::text);
  END IF;
  -- P5 future-dated insert allowed while today locked
  v_res := public.hard_stop_decide('{"id":"acc-A","initial_balance":50000,"rules":{"trailingMaxDrawdown":2000,"enableHardStop":true,"maxDailyLoss":1000,"maxDailyLossType":"$"}}'::jsonb, '[{"id":"t1","account_id":"acc-A","pnl":-1000,"date":"2026-03-10T10:00:00.000Z"}]'::jsonb, 'UTC', 'INSERT', NULL, '{"account_id":"acc-A","pnl":-1,"date":"2026-03-12T10:00:00.000Z"}'::jsonb, '2026-03-10T15:00:00Z'::timestamptz);
  v_run := v_run + 1;
  IF NOT coalesce((v_res->>'status') IS NOT DISTINCT FROM 'locked'
         AND (v_res->>'dayKey') IS NOT DISTINCT FROM '2026-03-10'
         AND abs((v_res->>'lossToday')::numeric - (1000)::numeric) <= 1e-9
         AND abs((v_res->>'limit')::numeric - (1000)::numeric) <= 1e-9
         AND (v_res->>'allowed') = 'true'
         AND (v_res->>'code') IS NOT DISTINCT FROM NULL, false) THEN
    v_fail := v_fail || ('P5 future-dated insert allowed while today locked' || ': ' || v_res::text);
  END IF;
  -- P5 batch: several trades of the same day add up, other account ignored
  v_res := public.hard_stop_decide('{"id":"acc-A","initial_balance":50000,"rules":{"trailingMaxDrawdown":2000,"enableHardStop":true,"maxDailyLoss":1000,"maxDailyLossType":"$"}}'::jsonb, '[{"id":"t1","account_id":"acc-A","pnl":-400,"date":"2026-03-10T09:00:00.000Z"},{"id":"t2","account_id":"acc-A","pnl":-300,"date":"2026-03-10T10:00:00.000Z"},{"id":"t3","account_id":"acc-A","pnl":-300,"date":"2026-03-10T11:00:00.000Z"},{"id":"tb","account_id":"acc-B","pnl":-5000,"date":"2026-03-10T11:00:00.000Z"}]'::jsonb, 'UTC', 'INSERT', NULL, '{"account_id":"acc-A","pnl":-1}'::jsonb, '2026-03-10T15:00:00Z'::timestamptz);
  v_run := v_run + 1;
  IF NOT coalesce((v_res->>'status') IS NOT DISTINCT FROM 'locked'
         AND (v_res->>'dayKey') IS NOT DISTINCT FROM '2026-03-10'
         AND abs((v_res->>'lossToday')::numeric - (1000)::numeric) <= 1e-9
         AND abs((v_res->>'limit')::numeric - (1000)::numeric) <= 1e-9
         AND (v_res->>'allowed') = 'false'
         AND (v_res->>'code') IS NOT DISTINCT FROM 'HARD_STOP', false) THEN
    v_fail := v_fail || ('P5 batch: several trades of the same day add up, other account ignored' || ': ' || v_res::text);
  END IF;
  -- P5 batch below limit: other account loss does not lock this account
  v_res := public.hard_stop_decide('{"id":"acc-A","initial_balance":50000,"rules":{"trailingMaxDrawdown":2000,"enableHardStop":true,"maxDailyLoss":1000,"maxDailyLossType":"$"}}'::jsonb, '[{"id":"t1","account_id":"acc-A","pnl":-400,"date":"2026-03-10T09:00:00.000Z"},{"id":"tb","account_id":"acc-B","pnl":-5000,"date":"2026-03-10T11:00:00.000Z"}]'::jsonb, 'UTC', 'INSERT', NULL, '{"account_id":"acc-A","pnl":-1}'::jsonb, '2026-03-10T15:00:00Z'::timestamptz);
  v_run := v_run + 1;
  IF NOT coalesce((v_res->>'status') IS NOT DISTINCT FROM 'ok'
         AND (v_res->>'dayKey') IS NOT DISTINCT FROM '2026-03-10'
         AND abs((v_res->>'lossToday')::numeric - (400)::numeric) <= 1e-9
         AND abs((v_res->>'limit')::numeric - (1000)::numeric) <= 1e-9
         AND (v_res->>'allowed') = 'true'
         AND (v_res->>'code') IS NOT DISTINCT FROM NULL, false) THEN
    v_fail := v_fail || ('P5 batch below limit: other account loss does not lock this account' || ': ' || v_res::text);
  END IF;
  -- P5 percent limit with initial_balance 0: limit <= 0 is not configured (off), add allowed
  v_res := public.hard_stop_decide('{"id":"acc-A","rules":{"trailingMaxDrawdown":2000,"enableHardStop":true,"maxDailyLoss":2,"maxDailyLossType":"%"},"initial_balance":0}'::jsonb, '[{"id":"t-loss","account_id":"acc-A","pnl":-1000,"date":"2026-03-10T10:00:00.000Z"}]'::jsonb, 'UTC', 'INSERT', NULL, '{"account_id":"acc-A","pnl":-1}'::jsonb, '2026-03-10T15:00:00Z'::timestamptz);
  v_run := v_run + 1;
  IF NOT coalesce((v_res->>'status') IS NOT DISTINCT FROM 'off'
         AND (v_res->>'dayKey') IS NOT DISTINCT FROM '2026-03-10'
         AND abs((v_res->>'lossToday')::numeric - (1000)::numeric) <= 1e-9
         AND (v_res->>'limit') IS NULL
         AND (v_res->>'allowed') = 'true'
         AND (v_res->>'code') IS NOT DISTINCT FROM NULL, false) THEN
    v_fail := v_fail || ('P5 percent limit with initial_balance 0: limit <= 0 is not configured (off), add allowed' || ': ' || v_res::text);
  END IF;
  -- P5 percent limit with negative initial_balance: limit <= 0 is not configured (off), add allowed
  v_res := public.hard_stop_decide('{"id":"acc-A","rules":{"trailingMaxDrawdown":2000,"enableHardStop":true,"maxDailyLoss":2,"maxDailyLossType":"%"},"initial_balance":-5000}'::jsonb, '[{"id":"t-loss","account_id":"acc-A","pnl":-1000,"date":"2026-03-10T10:00:00.000Z"}]'::jsonb, 'UTC', 'INSERT', NULL, '{"account_id":"acc-A","pnl":-1}'::jsonb, '2026-03-10T15:00:00Z'::timestamptz);
  v_run := v_run + 1;
  IF NOT coalesce((v_res->>'status') IS NOT DISTINCT FROM 'off'
         AND (v_res->>'dayKey') IS NOT DISTINCT FROM '2026-03-10'
         AND abs((v_res->>'lossToday')::numeric - (1000)::numeric) <= 1e-9
         AND (v_res->>'limit') IS NULL
         AND (v_res->>'allowed') = 'true'
         AND (v_res->>'code') IS NOT DISTINCT FROM NULL, false) THEN
    v_fail := v_fail || ('P5 percent limit with negative initial_balance: limit <= 0 is not configured (off), add allowed' || ': ' || v_res::text);
  END IF;
  -- SERVER-EXPECTED P5 percent decimal boundary: loss exactly 3% of 10000.10 (300.003): client float warn, server numeric locked
  v_res := public.hard_stop_decide('{"id":"acc-A","initial_balance":10000.1,"rules":{"trailingMaxDrawdown":2000,"enableHardStop":true,"maxDailyLoss":3,"maxDailyLossType":"%"}}'::jsonb, '[{"id":"t-loss","account_id":"acc-A","pnl":-300.003,"date":"2026-03-10T10:00:00.000Z"}]'::jsonb, 'UTC', NULL, NULL, NULL, '2026-03-10T15:00:00Z'::timestamptz);
  v_run := v_run + 1;
  IF NOT coalesce((v_res->>'status') IS NOT DISTINCT FROM 'locked'
         AND (v_res->>'dayKey') IS NOT DISTINCT FROM '2026-03-10'
         AND abs((v_res->>'lossToday')::numeric - (300.003)::numeric) <= 1e-9
         AND abs((v_res->>'limit')::numeric - (300.003)::numeric) <= 1e-9, false) THEN
    v_fail := v_fail || ('P5 percent decimal boundary: loss exactly 3% of 10000.10 (300.003): client float warn, server numeric locked' || ': ' || v_res::text);
  END IF;
  IF cardinality(v_fail) > 0 THEN
    RAISE EXCEPTION 'hard_stop golden FAIL %/%: %', cardinality(v_fail), v_run, array_to_string(v_fail, E'\n');
  END IF;
  IF v_run <> 69 THEN
    RAISE EXCEPTION 'hard_stop golden ran % cases, expected 69', v_run;
  END IF;
  RAISE NOTICE 'hard_stop golden PASS %/%', v_run, v_run;
END
$golden$;
